CREATE TABLE IF NOT EXISTS refund_request_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,refund_id BIGINT UNSIGNED NOT NULL,admin_user_id BIGINT UNSIGNED NULL,from_status VARCHAR(24) NOT NULL,to_status VARCHAR(24) NOT NULL,note VARCHAR(1000) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_refund_event_request(refund_id,id),CONSTRAINT fk_refund_event_request FOREIGN KEY(refund_id) REFERENCES refund_requests(id) ON DELETE RESTRICT,CONSTRAINT fk_refund_event_admin FOREIGN KEY(admin_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
